"""Regenerate the hatch-vcs version file from ``git describe`` -- no pip needed. The shared venv carries no
pip, so hardstand's old ``pip install -e .`` setup died on every fresh workspace up; this writes a
dev-sufficient ``crawlutron/_version.py`` (same module shape hatch-vcs emits). A real build overwrites it.
"""

from __future__ import annotations

import re
import shutil
import subprocess
import sys
from pathlib import Path

TEMPLATE = """\
# file generated by scripts/regen_version.py (git describe; replaced by hatch-vcs at build)
# don't change, don't track in version control
from __future__ import annotations

__all__ = [
    "__version__",
    "__version_tuple__",
    "version",
    "version_tuple",
    "__commit_id__",
    "commit_id",
]

version: str
__version__: str
__version_tuple__: tuple[int | str, ...]
version_tuple: tuple[int | str, ...]
commit_id: str | None
__commit_id__: str | None

__version__ = version = {ver!r}
__version_tuple__ = version_tuple = {vt!r}

__commit_id__ = commit_id = None
"""


def _describe() -> str:
    # Full path: the no-partial-path lint rule, and the venv-first PATH the
    # hardstand setup child gets resolves it the same way.
    git = shutil.which("git")
    if git is None:
        raise SystemExit("regen_version: git not found on PATH")
    return subprocess.run(
        [git, "describe", "--tags", "--long", "--always"],
        capture_output=True,
        text=True,
        check=True,
    ).stdout.strip()


def _version_parts(desc: str) -> tuple[str, tuple[int | str, ...]]:
    match = re.match(r"^v?(.*?)-(\d+)-g([0-9a-f]+)$", desc)
    if match:
        tag = f"{match.group(1)}.dev{match.group(2)}+g{match.group(3)}"
    else:
        tag = desc
    return tag, tuple(int(p) if p.isdigit() else p for p in re.split(r"[.\-]", tag))


def main() -> None:
    version, parts = _version_parts(_describe())
    write_target = Path("packages/core/crawlutron/_version.py")
    write_target.write_text(TEMPLATE.format(ver=version, vt=parts))
    print(f"wrote {write_target}: {version}")


if __name__ == "__main__":
    sys.exit(main())
